"""bo2zm: write a C++ file of static_asserts that pins every computed T6
layout (size, alignment, member offsets) to what 32-bit MSVC computes for
the same header. Compile it with the x86 compiler; a clean compile means the
generator's layout matches the compiler's byte for byte."""

import os


def write_check(h, header_path, out_path):
    lines = [
        '// Generated by crates/fastfile_t6/gen/layoutcheck.py. Compile with the x86 MSVC compiler.',
        '#define ARCH_x86',
        '#include <cstddef>',
        '#include <cstdint>',
        '#include "%s"' % header_path.replace('\\', '/'),
        'using namespace T6;',
        '#define CHECK_SIZE(T, n) static_assert(sizeof(T) == n, "size " #T)',
        '#define CHECK_ALIGN(T, n) static_assert(alignof(T) == n, "align " #T)',
        '#define CHECK_OFF(T, m, n) static_assert(offsetof(T, m) == n, "offset " #T "::" #m)',
    ]
    checks = 0
    for name in h.order:
        rec = h.records[name]
        if rec.anon:
            continue
        lines.append('CHECK_SIZE(%s, %d);' % (name, rec.size))
        lines.append('CHECK_ALIGN(%s, %d);' % (name, rec.align))
        checks += 2
        for m in rec.members:
            if m.anon or m.bits is not None:
                continue
            lines.append('CHECK_OFF(%s, %s, %d);' % (name, m.name, m.offset))
            checks += 1
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, 'w', encoding='utf-8', newline='\n') as f:
        f.write('\n'.join(lines) + '\n')
    return checks
